<script setup>
import { ref, reactive, onMounted } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import * as XLSX from 'xlsx';
import { hasStudentClassId } from './student-edit-compat.mjs';
const props = defineProps({ api: { type: Function, required: true } });
const rows = ref([]), classes = ref([]), loading = ref(false), busy = ref(false), total = ref(0), page = ref(1), pageSize = ref(20), keyword = ref(''), classFilter = ref('');
const editOpen = ref(false), editingId = ref(null), avatarData = ref('');
const form = reactive({displayName:'', studentId:'', password:'', classId:''});
const importOpen = ref(false), importClass = ref(''), importRows = ref([]), importText = ref(''), importNote = ref('');
const json = body => ({method:'POST',body:JSON.stringify(body)});
async function loadClasses(){ classes.value = (await props.api('/api/admin/classes?all=true')).rows || []; }
async function load(){ loading.value=true; try { const q=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value),q:keyword.value.trim(),classId:String(classFilter.value||'')}); const data=await props.api('/api/admin/users?'+q); rows.value=data.rows||[]; total.value=data.total||0; page.value=data.page||1; } catch(e){ElMessage.error(e.message);} finally {loading.value=false;} }
function search(){page.value=1;load();}
function openEdit(row){ if(row && !hasStudentClassId(row)){ElMessage.error('教师机服务尚未更新，请先重启服务后再编辑学生，以免影响班级归属。');return;} editingId.value=row?.id||null; Object.assign(form,{displayName:row?.displayName||'',studentId:row?.studentId||'',password:'',classId:row?.classId||''}); avatarData.value=''; editOpen.value=true; }
async function selectAvatar(event){const f=event.target.files?.[0]; if(!f)return; if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>160000){ElMessage.error('请选择不超过 160KB 的 PNG、JPG 或 WEBP 图片');event.target.value='';return;} avatarData.value=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('读取图片失败'));reader.readAsDataURL(f);}).catch(e=>{ElMessage.error(e.message);return '';});}
async function save(){if(busy.value)return;if(form.classId && !classes.value.some(c=>c.id===form.classId && c.isActive)){ElMessage.error('该班级已停用，请先启用或选择其他班级；留空会将学生移出班级。');return;}busy.value=true;try{ const payload={displayName:form.displayName.trim(),studentId:form.studentId.trim(),classId:form.classId||null}; if(editingId.value){ if(avatarData.value)payload.avatarData=avatarData.value; await props.api(`/api/admin/users/${editingId.value}/profile`,{method:'PATCH',body:JSON.stringify(payload)}); }else{payload.password=form.password;await props.api('/api/admin/users',json(payload));} editOpen.value=false; ElMessage.success('学生账号已保存'); await load();}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function toggle(row){try{await ElMessageBox.confirm(`确定${row.isActive?'停用':'启用'} ${row.displayName} 的账号？`, '确认操作',{type:'warning'});await props.api(`/api/admin/users/${row.id}/status`,{method:'PATCH',body:JSON.stringify({isActive:!row.isActive})});ElMessage.success('账号状态已更新');load();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message);}}
async function resetPassword(row){try{const result=await ElMessageBox.prompt(`为 ${row.displayName} 设置新密码。重置后学生需要重新登录。`, '重置密码',{inputType:'password',inputPlaceholder:'6–12 位纯数字或字母数字组合',confirmButtonText:'重置'});await props.api(`/api/admin/users/${row.id}/reset-password`,json({password:result.value}));ElMessage.success('密码已重置');}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message);}}
function parseText(){importRows.value=importText.value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const p=line.split(/[\t,，;；]|\s+/);return {studentId:p[0]||'',displayName:p[1]||'',error:''};}).filter(r=>r.studentId!=='学号');importNote.value='';}
async function loadFile(event){const file=event.target.files?.[0]; if(!file)return;try{const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});const ws=wb.Sheets[wb.SheetNames.includes('学生名单')?'学生名单':wb.SheetNames[0]];const data=XLSX.utils.sheet_to_json(ws,{header:1,raw:false,defval:''}); const idx=data.findIndex(r=>r.some(c=>String(c).trim()==='姓名')&&r.some(c=>String(c).trim()==='学号'));if(idx<0)throw new Error('请使用包含“学号”和“姓名”表头的表格');const head=data[idx].map(c=>String(c).trim()),sid=head.indexOf('学号'),name=head.indexOf('姓名');importRows.value=data.slice(idx+1).map(r=>({studentId:String(r[sid]||'').trim(),displayName:String(r[name]||'').trim(),error:''})).filter(r=>r.studentId||r.displayName);importNote.value=`已读取 ${importRows.value.length} 行，可直接编辑`; }catch(e){ElMessage.error(e.message);}event.target.value='';}
function template(){const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['学号','姓名'],['20250101','张三']]),'学生名单');XLSX.writeFile(book,'学生导入模板.xlsx');}
async function importStudents(){if(!importRows.value.length||busy.value)return;busy.value=true;try{const data=await props.api('/api/admin/users/import',json({rows:importRows.value.map(({studentId,displayName})=>({studentId,displayName})),classId:importClass.value||undefined}));const errors=new Map((data.errors||[]).map(e=>[e.line,e.message]));importRows.value=importRows.value.map((row,i)=>({...row,error:errors.get(i+1)||''})).filter(row=>row.error);importNote.value=`成功导入 ${data.imported} 人，失败 ${data.failed} 人${data.failed?'；失败行已保留，可修改后重试。':''}`;ElMessage.success(importNote.value);await load();}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
onMounted(async()=>{try{await Promise.all([loadClasses(),load()]);}catch(e){ElMessage.error(e.message);}});
</script>
<template>
<section class="student-admin"><header class="section-title"><div><h1>学生账号</h1><p>管理学生账号和班级归属。</p></div><div class="actions"><el-button @click="load">刷新</el-button><el-button @click="importOpen=true">导入学生</el-button><el-button type="primary" @click="openEdit()">新建学生</el-button></div></header>
<el-form inline @submit.prevent="search"><el-form-item><el-input v-model="keyword" placeholder="姓名、账号或学号" clearable @clear="search"/></el-form-item><el-form-item><el-select v-model="classFilter" placeholder="全部班级" clearable style="width:180px" @change="search"><el-option label="待分班" value="unassigned"/><el-option v-for="c in classes" :key="c.id" :label="c.name" :value="String(c.id)"/></el-select></el-form-item><el-button type="primary" native-type="submit">查询</el-button></el-form>
<el-table v-loading="loading" :data="rows" height="100%" empty-text="没有找到学生"><el-table-column prop="displayName" label="姓名" min-width="100"/><el-table-column prop="studentId" label="学号" min-width="130"/><el-table-column prop="username" label="账号" min-width="110"/><el-table-column prop="className" label="班级" min-width="150"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.isActive?'success':'info'">{{row.isActive?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="attempts" label="挑战次数" width="90"/><el-table-column prop="personalBest" label="最好成绩" width="90"/><el-table-column label="最后登录" min-width="120"><template #default="{row}">{{row.lastLoginAt?new Date(row.lastLoginAt).toLocaleDateString('zh-CN'):'—'}}</template></el-table-column><el-table-column label="注册时间" min-width="120"><template #default="{row}">{{row.createdAt?new Date(row.createdAt).toLocaleDateString('zh-CN'):'—'}}</template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="primary" @click="resetPassword(row)">重置密码</el-button><el-button link :type="row.isActive?'danger':'success'" @click="toggle(row)">{{row.isActive?'停用':'启用'}}</el-button></template></el-table-column></el-table><div class="pager"><span>共 {{total}} 人</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50]" :total="total" layout="sizes, prev, pager, next" @size-change="page=1; load()" @current-change="load"/></div>
<el-dialog v-model="editOpen" :title="editingId?'编辑学生账号':'新建学生'" width="min(560px, 94vw)"><el-form label-position="top" @submit.prevent="save"><el-form-item label="学生姓名"><el-input v-model="form.displayName" maxlength="12"/></el-form-item><el-form-item label="学号"><el-input v-model="form.studentId" maxlength="32"/></el-form-item><el-form-item v-if="!editingId" label="初始密码（留空使用学号）"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="所属班级"><el-select v-model="form.classId" clearable placeholder="暂不分班"><el-option v-for="c in classes" :key="c.id" :label="c.name + (c.isActive ? '' : '（已停用）')" :value="c.id" :disabled="!c.isActive"/></el-select></el-form-item><el-form-item v-if="editingId" label="更换头像"><input type="file" accept="image/png,image/jpeg,image/webp" @change="selectAvatar"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">保存</el-button></el-form></el-dialog>
<el-dialog v-model="importOpen" title="导入学生" width="min(800px, 96vw)"><p>导入前可编辑名单；失败行会保留，修正后可继续提交。初始密码为学号。</p><el-select v-model="importClass" clearable placeholder="选择班级（可选）"><el-option v-for="c in classes.filter(x=>x.isActive)" :key="c.id" :label="c.name" :value="c.id"/></el-select><div class="import-controls"><el-button @click="template">下载 Excel 模板</el-button><input type="file" accept=".xlsx,.xls,.csv" @change="loadFile"/></div><el-input v-model="importText" type="textarea" :rows="3" placeholder="粘贴名单，每行：学号,姓名"/><el-button @click="parseText">预览粘贴名单</el-button><p v-if="importNote">{{importNote}}</p><el-table :data="importRows" max-height="300"><el-table-column label="学号"><template #default="{row}"><el-input v-model="row.studentId"/></template></el-table-column><el-table-column label="姓名"><template #default="{row}"><el-input v-model="row.displayName"/></template></el-table-column><el-table-column prop="error" label="错误" min-width="160"/><el-table-column width="65"><template #default="{$index}"><el-button link type="danger" @click="importRows.splice($index,1)">删除</el-button></template></el-table-column></el-table><template #footer><el-button @click="importOpen=false">关闭</el-button><el-button type="primary" :loading="busy" :disabled="!importRows.length" @click="importStudents">导入 {{importRows.length}} 人</el-button></template></el-dialog>
</section>
</template>
<style scoped>.section-title{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:24px}.section-title h1{margin:0}.section-title p{color:#6b7280}.actions,.import-controls,.pager{display:flex;gap:10px;align-items:center}.pager{justify-content:space-between;margin-top:20px}.import-controls{margin:14px 0}@media(max-width:700px){.section-title{align-items:flex-start;flex-direction:column}.actions{flex-wrap:wrap}}</style>
